from sympy import *
from sympy.solvers.solveset import solvify, solveset
x=Symbol('x')
exprs=[sin(exp(x)), exp(sin(x)), sin(x)-x, sin(x)-x/2, x*cos(x)-sin(x)]
for expr in exprs:
    print('\n', expr)
    try:
        sr=solveset(expr, x, S.Reals)
        print('solveset', sr)
    except Exception as e:
        print('solveset err', e)
    try:
        print('solvify', solvify(expr, x, S.Reals))
    except Exception as e:
        print('solvify err', type(e).__name__, e)
    try:
        print('Eq.as_set', Eq(expr,0).as_set())
    except Exception as e:
        print('as_set err', type(e).__name__, e)
